arguments.command:
cd /app/categorizationapp && python3 - <<'EOF'
import re, glob, os, sys
sys.path.insert(0,'.')
from categorizationapp.UtilityScripts import BankRegexConstants as B, RegexConstants as R
consts={}
for m in (B,R):
    for k,v in vars(m).items():
        if isinstance(v,str) and not k.startswith('_'): consts[k]=v

call = re.compile(r'py_extract\(\s*([^,]+?),\s*(?:pat=)?(.+?),\s*index=(\d+)\s*\)')
for f in sorted(glob.glob('categorizationapp/**/*.py', recursive=True)):
    for i,line in enumerate(open(f), 1):
        for m in call.finditer(line):
            src, pat, idx = m.group(1).strip(), m.group(2).strip(), int(m.group(3))
            lit=None
            if pat in consts: lit=consts[pat]
            elif (pat.startswith('"') and pat.endswith('"')) or (pat.startswith("'") and pat.endswith("'")):
                lit = eval(pat)
            if lit is None: continue
            try:
                ng = re.compile(lit).groups
            except Exception as e:
                print("BADREGEX",f,i,pat,e); continue
            if ng == 0 or idx >= ng or (ng>1 and idx != ng-1):
                print(f"{f}:{i} idx={idx} groups={ng} pat={pat} -> {lit[:90]!r}")
EOF

