cd /tmp/opencode && python3 snapshot.py after.json 2>&1 | grep -v INFO | tail -2 && python3 - <<'EOF'
import json
b=json.load(open('before.json')); a=json.load(open('after.json'))
assert b.keys()==a.keys()
n=0
for k in b:
    for i,(rb,ra) in enumerate(zip(b[k],a[k])):
        d={f:(rb[f],ra[f]) for f in rb if rb[f]!=ra[f]}
        if d:
            n+=1
            print(f"{k} #{i} {rb['type']:6} {rb['description'][:55]!r}")
            for f,(x,y) in d.items(): print(f"      {f}: {x!r} -> {y!r}")
print('changed rows:', n, 'of', sum(len(v) for v in b.values()))
EOF

